<?php require_once __DIR__ . '/layout.php';
if(isset($_GET['delete'])){ $id=(int)$_GET['delete']; save_data('users', delete_by_id(load_data('users'),$id)); save_data('requests', array_values(array_filter(load_data('requests'), fn($r)=>(int)$r['user_id']!==$id))); redirect('users.php'); }
$users=users_all(); $req=load_data('requests'); page_header('Users','users'); ?>
<div class="card"><h2>Users</h2><a class="btn" href="user_form.php">Add user</a></div><div class="card"><table><thead><tr><th>Full name</th><th>Department</th><th>Office</th><th>Phone</th><th>Requests</th><th></th></tr></thead><tbody><?php foreach($users as $u): $cnt=count(array_filter($req, fn($r)=>(int)$r['user_id']===(int)$u['id'])); ?><tr><td><?= h($u['full_name']) ?></td><td><?= h($u['department']) ?></td><td><?= h($u['office']) ?></td><td><?= h($u['phone']) ?></td><td><?= $cnt ?></td><td class="actions"><a class="btn small" href="user_form.php?id=<?= (int)$u['id'] ?>">Edit</a><a class="btn small danger" onclick="return confirm('Delete this user?')" href="users.php?delete=<?= (int)$u['id'] ?>">Delete</a></td></tr><?php endforeach; ?><?php if(!$users): ?><tr><td colspan="6">There are no users yet.</td></tr><?php endif; ?></tbody></table></div><?php page_footer(); ?>
